namespace AiBox.DevPortal.Services;

/// <summary>
/// Manages agent instructions.
/// </summary>public sealed class AgentInstructionService(IWebHostEnvironment environment)
{
    /// <summary>
/// Builds the agent instruction context asynchronously.
/// </summary>
/// <param name="filePaths">The file paths to include in the context.</param>
/// <returns>The built agent instruction context.</returns>public async Task<AgentInstructionContext> BuildContextAsync(IEnumerable<string> filePaths)
    {
        return await BuildContextAsync(GetRootPath(), filePaths);
    }

    /// <summary>
/// Builds the agent instruction context asynchronously.
/// </summary>
/// <param name="projectRoot">The root path of the project.</param>
/// <param name="filePaths">The file paths to include in the context.</param>
/// <returns>The built agent instruction context.</returns>public async Task<AgentInstructionContext> BuildContextAsync(string projectRoot, IEnumerable<string> filePaths)
    {
        var rootPath = GetRootPath(projectRoot);
        var relevantFiles = await FindRelevantAgentFilesAsync(rootPath, filePaths);
        var files = new List<AgentInstructionFile>(relevantFiles.Count);

        foreach (var relativePath in relevantFiles)
        {
            var fullPath = Path.Combine(rootPath, relativePath.Replace('/', Path.DirectorySeparatorChar));
            var content = await File.ReadAllTextAsync(fullPath);

            files.Add(new AgentInstructionFile
            {
                RelativePath = relativePath,
                Content = content
            });
        }

        return new AgentInstructionContext
        {
            RelevantAgentFiles = relevantFiles,
            Files = files,
            CombinedText = BuildCombinedText(files)
        };
    }

    /// <summary>
/// Finds relevant agent files asynchronously.
/// </summary>
/// <param name="filePaths">The file paths to search for relevant agent files.</param>
/// <returns>A list of relevant agent files.</returns>public Task<List<string>> FindRelevantAgentFilesAsync(IEnumerable<string> filePaths)
    {
        return FindRelevantAgentFilesAsync(GetRootPath(), filePaths);
    }

    /// <summary>
/// Finds relevant agent files asynchronously.
/// </summary>
/// <param name="projectRoot">The root path of the project.</param>
/// <param name="filePaths">The file paths to search for relevant agent files.</param>
/// <returns>A list of relevant agent files.</returns>public Task<List<string>> FindRelevantAgentFilesAsync(string projectRoot, IEnumerable<string> filePaths)
    {
        ArgumentNullException.ThrowIfNull(filePaths);

        var rootPath = GetRootPath(projectRoot);
        var candidateFiles = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        foreach (var filePath in filePaths.Where(path => !string.IsNullOrWhiteSpace(path)).Distinct(StringComparer.OrdinalIgnoreCase))
        {
            var normalizedRelativePath = NormalizeRelativePath(rootPath, filePath);
            foreach (var candidate in EnumerateAgentFileCandidates(normalizedRelativePath))
            {
                var fullPath = Path.Combine(rootPath, candidate.Replace('/', Path.DirectorySeparatorChar));

                if (File.Exists(fullPath))
                {
                    candidateFiles.Add(candidate);
                }
            }
        }

        var ordered = candidateFiles
            .OrderBy(path => GetPathDepth(path), Comparer<int>.Default)
            .ThenBy(path => path, StringComparer.OrdinalIgnoreCase)
            .ToList();

        return Task.FromResult(ordered);
    }

    /// <summary>
/// Gets the root path of the application.
/// </summary>
/// <returns>The root path of the application.</returns>private string GetRootPath()
    {
        return GetRootPath(environment.ContentRootPath);
    }

    /// <summary>
/// Gets the absolute path of the root directory.
/// </summary>
/// <param name="rootPath">The relative or absolute root path.</param>
/// <returns>The absolute path of the root directory.</returns>private static string GetRootPath(string? rootPath)
    {
        if (string.IsNullOrWhiteSpace(rootPath))
        {
            throw new InvalidOperationException("The application content root was not configured.");
        }

        return Path.GetFullPath(rootPath);
    }

    /// <summary>
/// Normalizes a relative file path to an absolute path.
/// </summary>
/// <param name="rootPath">The root path of the project.</param>
/// <param name="filePath">The relative file path.</param>
/// <returns>The normalized absolute path.</returns>private static string NormalizeRelativePath(string rootPath, string filePath)
    {
        var trimmedPath = filePath.Trim();
        var fullPath = Path.GetFullPath(Path.IsPathRooted(trimmedPath) ? trimmedPath : Path.Combine(rootPath, trimmedPath));
        var normalizedRootPath = rootPath.TrimEnd(Path.DirectorySeparatorChar) + Path.DirectorySeparatorChar;

        if (!fullPath.StartsWith(normalizedRootPath, StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException($"File path '{trimmedPath}' is outside the project root.");
        }

        return Path.GetRelativePath(rootPath, fullPath).Replace(Path.DirectorySeparatorChar, '/');
    }

    /// <summary>
/// Enumerates possible agent file candidates for a given relative file path.
/// </summary>
/// <param name="relativeFilePath">The relative file path.</param>
/// <returns>An enumerable of candidate file paths.</returns>private static IEnumerable<string> EnumerateAgentFileCandidates(string relativeFilePath)
    {
        yield return "AGENTS.md";

        var directoryPath = Path.GetDirectoryName(relativeFilePath);
        if (string.IsNullOrWhiteSpace(directoryPath))
        {
            yield break;
        }

        var segments = directoryPath.Split('/', StringSplitOptions.RemoveEmptyEntries);
        var current = new List<string>(segments.Length);

        foreach (var segment in segments)
        {
            current.Add(segment);
            yield return string.Join('/', current) + "/AGENTS.md";
        }
    }

    /// <summary>
/// Gets the depth of a path.
/// </summary>
/// <param name="path">The path.</param>
/// <returns>The depth of the path.</returns>private static int GetPathDepth(string path)
    {
        return path.Equals("AGENTS.md", StringComparison.OrdinalIgnoreCase)
            ? 0
            : path.Count(character => character == '/');
    }

    /// <summary>
/// Builds combined text from a list of agent instruction files.
/// </summary>
/// <param name="files">The list of agent instruction files.</param>
/// <returns>The combined text.</returns>private static string BuildCombinedText(IReadOnlyList<AgentInstructionFile> files)
    {
        if (files.Count == 0)
        {
            return string.Empty;
        }

        var builder = new StringBuilder();

        foreach (var file in files)
        {
            if (builder.Length > 0)
            {
                builder.AppendLine();
            }

            builder.AppendLine($"FILE: {file.RelativePath}");
            builder.AppendLine(file.Content.TrimEnd());
        }

        return builder.ToString();
    }
}
